from io import StringIO
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
import pandas as pd

REPORT_START = datetime(2024,3,15,tzinfo=timezone.utc)
REPORT_END = datetime(2024,3,16,tzinfo=timezone.utc)
BTU_TO_KWH = 0.00029307107

farms_df = pd.read_csv('/app/dataset/farms.csv')
farms_df['farm_name_key'] = farms_df['farm_name'].str.strip().str.lower()
reg_df = pd.read_csv('/app/dataset/farm_registry.csv')
reg_df['farm_name_key'] = reg_df['farm_name'].str.strip().str.lower()
meta_df = reg_df.merge(farms_df[['farm_name_key','timezone']], on='farm_name_key', how='left')
cal = json.load(open('/app/dataset/sensors_calibration.json'))['enterprise_platform']['deployment_environments']['system_config']['farms']

maint_local = {
    'FARM_C': [(datetime(2024,3,16,8,0), datetime(2024,3,16,12,0))],
    'FARM_F': [(datetime(2024,3,15,12,0), datetime(2024,3,15,14,0))],
}

def parse_timestamp(value):
    if pd.isna(value):
        return None
    s = str(value).strip()
    if not s:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S','%d.%m.%Y %H:%M:%S'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None

def parse_number(value):
    if pd.isna(value):
        return math.nan
    s = str(value).strip()
    if not s:
        return math.nan
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return math.nan


def read_df(path):
    raw = open(path,'rb').read()
    enc = 'utf-16' if raw.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8'
    text = raw.decode(enc)
    lines = text.splitlines()
    header = lines[3]
    sep = ';' if ';' in header else ','
    return pd.read_csv(StringIO('\n'.join(lines[3:])), sep=sep, dtype=str).drop_duplicates()


def cadence_minutes(local_dts):
    vals = sorted(dt for dt in local_dts if dt is not None)
    diffs = []
    for a,b in zip(vals, vals[1:]):
        delta = int((b-a).total_seconds()//60)
        if delta > 0:
            diffs.append(delta)
    if not diffs:
        return 0
    return pd.Series(diffs).mode().iloc[0]

answer = {}
for _, farm in meta_df.iterrows():
    farm_id = farm['farm_id']
    tz = ZoneInfo(farm['timezone'])
    info = cal[farm_id]
    value_col = info['calibration_data']['value_column_name']
    offset = info['calibration_data']['calibration_offset']
    reading_type = info['sensor_info']['reading_type'].lower()
    unit = info['sensor_info']['unit'].lower()

    df = read_df(f'/app/dataset/production_{farm_id}.csv')
    ts_col = next(c for c in df.columns if c.strip().startswith('timestamp'))
    temp_col = next(c for c in df.columns if c.strip() == 'inverter_temperature_C')
    if value_col not in df.columns:
        raise KeyError((farm_id, value_col, df.columns.tolist()))

    local_ts = df[ts_col].map(parse_timestamp)
    utc_ts = local_ts.map(lambda x: x.replace(tzinfo=tz).astimezone(timezone.utc) if x is not None else None)
    temps = df[temp_col].map(parse_number)
    values = df[value_col].map(parse_number)

    # shutdown windows
    invalid_after_spike = pd.Series(False, index=df.index)
    spike_times = [ts for ts,temp in zip(utc_ts, temps) if ts is not None and pd.notna(temp) and temp > 85.0]
    for spike in spike_times:
        invalid_after_spike |= utc_ts.map(lambda t: t is not None and spike < t <= spike + timedelta(minutes=45))

    # maintenance windows
    invalid_maintenance = pd.Series(False, index=df.index)
    for start_local, end_local in maint_local.get(farm_id, []):
        start_utc = start_local.replace(tzinfo=tz).astimezone(timezone.utc)
        end_utc = end_local.replace(tzinfo=tz).astimezone(timezone.utc)
        invalid_maintenance |= utc_ts.map(lambda t: t is not None and start_utc <= t < end_utc)

    in_window = utc_ts.map(lambda t: t is not None and REPORT_START <= t < REPORT_END)

    true_vals = values - offset
    valid_vals = true_vals.where(true_vals >= 0)

    if reading_type == 'energy':
        if unit == 'wh':
            energy = valid_vals / 1000.0
        elif unit == 'kwh':
            energy = valid_vals
        elif unit == 'mwh':
            energy = valid_vals * 1000.0
        elif unit == 'btu':
            energy = valid_vals * BTU_TO_KWH
        else:
            raise ValueError((farm_id, unit))
    elif reading_type == 'power':
        cm = cadence_minutes(local_ts)
        factor = cm / 60.0
        energy = valid_vals * factor
    else:
        raise ValueError(reading_type)

    mask = in_window & ~invalid_after_spike & ~invalid_maintenance & energy.notna()
    total = energy[mask].sum()
    answer[farm_id] = round(float(total))
    print(farm_id, 'cadence', cadence_minutes(local_ts), 'rows_used', int(mask.sum()), 'total', total)

print('ANSWER', answer)
