from __future__ import annotations

import json
import math
from datetime import datetime, timedelta, timezone
from io import StringIO
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATASET_DIR = Path("/app/dataset")
REPORT_START_UTC = datetime(2024, 3, 15, 0, 0, 0, tzinfo=timezone.utc)
REPORT_END_UTC = datetime(2024, 3, 16, 0, 0, 0, tzinfo=timezone.utc)
BTU_TO_KWH = 0.00029307107

# Derived from maintenance_notes.txt. Only successfully completed windows apply.
MAINTENANCE_WINDOWS_LOCAL: dict[str, list[tuple[datetime, datetime]]] = {
    "FARM_C": [(datetime(2024, 3, 16, 8, 0, 0), datetime(2024, 3, 16, 12, 0, 0))],
    "FARM_F": [(datetime(2024, 3, 15, 12, 0, 0), datetime(2024, 3, 15, 14, 0, 0))],
}


def parse_timestamp(value: object) -> datetime | None:
    if pd.isna(value):
        return None
    text = str(value).strip()
    if not text:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


def parse_number(value: object) -> float:
    if pd.isna(value):
        return math.nan
    text = str(value).strip()
    if not text:
        return math.nan

    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(",", ".")

    try:
        return float(text)
    except ValueError:
        return math.nan


def read_production_csv(path: Path) -> pd.DataFrame:
    raw = path.read_bytes()
    encoding = "utf-16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8"
    text = raw.decode(encoding)
    lines = text.splitlines()
    header = lines[3]
    separator = ";" if ";" in header else ","
    return pd.read_csv(StringIO("\n".join(lines[3:])), sep=separator, dtype=str).drop_duplicates()


def infer_cadence_minutes(local_timestamps: list[datetime | None]) -> int:
    parsed = sorted(timestamp for timestamp in local_timestamps if timestamp is not None)
    deltas: list[int] = []
    for previous, current in zip(parsed, parsed[1:]):
        delta_minutes = int((current - previous).total_seconds() // 60)
        if delta_minutes > 0:
            deltas.append(delta_minutes)
    if not deltas:
        return 0
    return int(pd.Series(deltas).mode().iloc[0])


def load_farm_metadata() -> pd.DataFrame:
    farms = pd.read_csv(DATASET_DIR / "farms.csv")
    farms["farm_name_key"] = farms["farm_name"].str.strip().str.lower()

    registry = pd.read_csv(DATASET_DIR / "farm_registry.csv")
    registry["farm_name_key"] = registry["farm_name"].str.strip().str.lower()

    return registry.merge(
        farms[["farm_name_key", "timezone"]],
        on="farm_name_key",
        how="left",
    )


def load_calibration() -> dict[str, dict[str, object]]:
    with (DATASET_DIR / "sensors_calibration.json").open() as handle:
        payload = json.load(handle)
    return payload["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def energy_series_kwh(
    farm_id: str,
    dataframe: pd.DataFrame,
    local_timestamps: list[datetime | None],
    calibration: dict[str, dict[str, object]],
) -> pd.Series:
    farm_config = calibration[farm_id]
    value_column = farm_config["calibration_data"]["value_column_name"]
    if value_column not in dataframe.columns:
        raise KeyError(f"{farm_id} missing value column {value_column!r}")

    reading_type = str(farm_config["sensor_info"]["reading_type"]).lower()
    unit = str(farm_config["sensor_info"]["unit"]).lower()
    calibration_offset = float(farm_config["calibration_data"]["calibration_offset"])

    values = pd.Series([parse_number(value) for value in dataframe[value_column]], index=dataframe.index)
    true_values = values - calibration_offset
    true_values = true_values.where(true_values >= 0)

    if reading_type == "energy":
        if unit == "wh":
            return true_values / 1000.0
        if unit == "kwh":
            return true_values
        if unit == "mwh":
            return true_values * 1000.0
        if unit == "btu":
            return true_values * BTU_TO_KWH
        raise ValueError(f"Unsupported energy unit for {farm_id}: {unit}")

    if reading_type == "power":
        cadence_minutes = infer_cadence_minutes(local_timestamps)
        return true_values * (cadence_minutes / 60.0)

    raise ValueError(f"Unsupported reading type for {farm_id}: {reading_type}")


def build_shutdown_mask(
    dataframe: pd.DataFrame,
    utc_timestamps: list[datetime | None],
) -> pd.Series:
    temperature_column = next(column for column in dataframe.columns if column.strip() == "inverter_temperature_C")
    temperatures = [parse_number(value) for value in dataframe[temperature_column]]

    mask = pd.Series(False, index=dataframe.index)
    spike_times = [
        timestamp
        for timestamp, temperature in zip(utc_timestamps, temperatures)
        if timestamp is not None and not math.isnan(temperature) and temperature > 85.0
    ]
    for spike_time in spike_times:
        mask |= pd.Series(
            [
                timestamp is not None and spike_time < timestamp <= spike_time + timedelta(minutes=45)
                for timestamp in utc_timestamps
            ],
            index=dataframe.index,
        )
    return mask


def build_maintenance_mask(
    farm_id: str,
    timezone_name: str,
    dataframe: pd.DataFrame,
    utc_timestamps: list[datetime | None],
) -> pd.Series:
    tz = ZoneInfo(timezone_name)
    mask = pd.Series(False, index=dataframe.index)

    for start_local, end_local in MAINTENANCE_WINDOWS_LOCAL.get(farm_id, []):
        start_utc = start_local.replace(tzinfo=tz).astimezone(timezone.utc)
        end_utc = end_local.replace(tzinfo=tz).astimezone(timezone.utc)
        mask |= pd.Series(
            [
                timestamp is not None and start_utc <= timestamp < end_utc
                for timestamp in utc_timestamps
            ],
            index=dataframe.index,
        )

    return mask


def answer() -> dict[str, int]:
    farm_metadata = load_farm_metadata()
    calibration = load_calibration()

    totals: dict[str, int] = {}
    for farm in farm_metadata.itertuples(index=False):
        farm_id = farm.farm_id
        timezone_name = farm.timezone
        tz = ZoneInfo(timezone_name)

        dataframe = read_production_csv(DATASET_DIR / f"production_{farm_id}.csv")
        timestamp_column = next(column for column in dataframe.columns if column.strip().startswith("timestamp"))

        local_timestamps = [parse_timestamp(value) for value in dataframe[timestamp_column]]
        utc_timestamps = [
            timestamp.replace(tzinfo=tz).astimezone(timezone.utc) if timestamp is not None else None
            for timestamp in local_timestamps
        ]

        report_window_mask = pd.Series(
            [
                timestamp is not None and REPORT_START_UTC <= timestamp < REPORT_END_UTC
                for timestamp in utc_timestamps
            ],
            index=dataframe.index,
        )
        shutdown_mask = build_shutdown_mask(dataframe, utc_timestamps)
        maintenance_mask = build_maintenance_mask(farm_id, timezone_name, dataframe, utc_timestamps)
        energy_kwh = energy_series_kwh(farm_id, dataframe, local_timestamps, calibration)

        valid_mask = report_window_mask & ~shutdown_mask & ~maintenance_mask & energy_kwh.notna()
        totals[farm_id] = round(float(energy_kwh[valid_mask].sum())) if valid_mask.any() else 0

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as handle:
        json.dump(answer(), handle, default=list)

